-- ----------------------------
-- Table structure for etcitem
-- ----------------------------
DROP TABLE IF EXISTS `etcitem`;
CREATE TABLE `etcitem`  (
  `item_id` int(10) UNSIGNED NOT NULL AUTO_INCREMENT,
  `name` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `classname` varchar(100) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT '0',
  `name_id` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `item_type` varchar(40) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `use_type` varchar(20) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `material` varchar(45) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL DEFAULT '',
  `weight` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `invgfx` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `grdgfx` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `itemdesc_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `stackable` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `max_charge_count` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `dmg_small` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `dmg_large` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `min_lvl` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `max_lvl` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `bless` int(2) UNSIGNED NOT NULL DEFAULT 1,
  `trade` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `cant_delete` int(2) UNSIGNED NOT NULL DEFAULT 0,
  `delay_id` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `delay_time` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `delay_effect` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `food_volume` int(10) UNSIGNED NOT NULL DEFAULT 0,
  `save_at_once` tinyint(1) UNSIGNED NOT NULL DEFAULT 1,
  `max_use_time` int(2) NULL DEFAULT 0,
  `MeteLevel` int(10) NULL DEFAULT 0 COMMENT '轉生使用判斷(設置1代表1轉以上才可使用此道具)',
  `MeteLevelMAX` int(10) NULL DEFAULT 10,
  `use_camp` int(5) NULL DEFAULT 0 COMMENT '1-A.2-B.4-C.7-共用',
  `use_career` int(5) NOT NULL DEFAULT 255 COMMENT '1王族.2騎士.4妖精.8法師.16黑妖.32龍騎.64幻術.128戰士.127共用',
  `cant_be_sold` tinyint(1) NULL DEFAULT 0 COMMENT '禁止販賣NPC',
  `是否可存倉` int(10) NULL DEFAULT 0,
  `是否可存血盟倉` int(10) NULL DEFAULT 0,
  PRIMARY KEY (`item_id`) USING BTREE,
  INDEX `item_id`(`item_id`) USING BTREE
) ENGINE = MyISAM AUTO_INCREMENT = 7002201 CHARACTER SET = utf8 COLLATE = utf8_general_ci ROW_FORMAT = Dynamic;

